#-----------------------------------------------------------------#
# 7. Plot eight figures: six triads in one horizontal row
#-----------------------------------------------------------------#
group_cols <- c('non_pCR' = '#E07A73', 'pCR' = '#5AB49B')
correlation_cols <- c('negative' = '#3B6EA8', 'zero' = 'grey92', 'positive' = '#B14A4A')

plot_two_function_triad_set <- function(triad_table, output_file, plot_title) {
  if (nrow(triad_table) != 6L) {
    stop('Each figure must contain exactly six triads.', call. = FALSE)
  }
  
  # Fixed display order: functional group -> metabolite -> species -> gene.
  triad_table <- triad_table %>%
    arrange(group_order, Metabolite, Species, Gene) %>%
    group_by(group_order, display_group) %>%
    mutate(panel_in_group = row_number()) %>%
    ungroup() %>%
    mutate(
      panel_number = row_number(),
      panel = factor(
        paste0('#', panel_number),
        levels = paste0('#', seq_len(n()))
      )
    )
  
  triangle_width <- 1.44
  triangle_height <- sqrt(3) / 2 * triangle_width
  
  node_data <- bind_rows(lapply(seq_len(nrow(triad_table)), function(i) {
    tibble(
      panel = triad_table$panel[i],
      x = c(0, triangle_width / 2, triangle_width),
      y = c(0, triangle_height, 0),
      label = c(
        str_replace_all(triad_table$Species[i], '_', ' '),
        str_replace_all(triad_table$Metabolite[i], '_', ' '),
        triad_table$Gene[i]
      ),
      node_effect = c(
        triad_table$species_effect[i],
        triad_table$metabolite_effect[i],
        triad_table$gene_effect[i]
      ),
      label_x = c(-0.04, triangle_width / 2, triangle_width + 0.04),
      label_y = c(-0.16, triangle_height + 0.15, -0.16),
      hjust = c(0, 0.5, 1),
      fontface = c('italic', 'plain', 'bold')
    )
  }))
  
  edge_data <- bind_rows(lapply(seq_len(nrow(triad_table)), function(i) {
    tibble(
      panel = triad_table$panel[i],
      x = c(0, triangle_width / 2, 0),
      y = c(0, triangle_height, 0),
      xend = c(triangle_width / 2, triangle_width, triangle_width),
      yend = c(triangle_height, 0, 0),
      r = c(
        triad_table$species_met_r[i],
        triad_table$met_gene_r[i],
        triad_table$species_gene_r[i]
      ),
      p = c(
        triad_table$species_met_p[i],
        triad_table$met_gene_p[i],
        triad_table$species_gene_p[i]
      ),
      label_x = c(0.28, triangle_width - 0.28, triangle_width / 2),
      label_y = c(0.55 * triangle_height, 0.55 * triangle_height, -0.08)
    )
  })) %>%
    mutate(
      edge_label = paste0(
        'r=', sprintf('%.2f', r),
        case_when(
          p < 0.001 ~ '***',
          p < 0.01 ~ '**',
          p < 0.05 ~ '*',
          TRUE ~ ''
        )
      ),
      edge_linetype = ifelse(p < 0.05, 'solid', 'longdash')
    )
  
  finite_effect <- abs(node_data$node_effect[is.finite(node_data$node_effect)])
  effect_limit <- if (length(finite_effect) == 0) {
    1
  } else {
    max(1, quantile(finite_effect, 0.90, na.rm = TRUE))
  }
  
  node_data <- node_data %>%
    mutate(node_effect_plot = pmax(pmin(node_effect, effect_limit), -effect_limit))
  
  # Print each functional-group label only once, above the middle triad of
  # the corresponding three-triad block. Per-triad score/consistency text is
  # retained in the CSV output but removed from the figure.
  group_header_data <- triad_table %>%
    filter(panel_in_group == 2L) %>%
    transmute(
      panel,
      x = triangle_width / 2,
      y = triangle_height + 0.42,
      label = display_group
    )
  
  p_set <- ggplot() +
    geom_segment(
      data = edge_data,
      aes(
        x = x, y = y, xend = xend, yend = yend,
        color = r, linewidth = abs(r), linetype = edge_linetype
      ),
      lineend = 'round'
    ) +
    geom_text(
      data = edge_data,
      aes(x = label_x, y = label_y, label = edge_label),
      size = 2.35,
      color = 'grey20'
    ) +
    geom_point(
      data = node_data,
      aes(x = x, y = y, fill = node_effect_plot),
      shape = 21,
      size = 5.0,
      color = 'grey30',
      stroke = 0.5
    ) +
    geom_text(
      data = node_data,
      aes(
        x = label_x, y = label_y, label = label,
        hjust = hjust, fontface = fontface
      ),
      size = 2.5,
      color = 'grey15'
    ) +
    geom_text(
      data = group_header_data,
      aes(x = x, y = y, label = label),
      size = 2.3,
      fontface = 'bold',
      color = 'grey15',
      lineheight = 0.90
    ) +
    scale_color_gradient2(
      low = correlation_cols['negative'],
      mid = correlation_cols['zero'],
      high = correlation_cols['positive'],
      midpoint = 0,
      limits = c(-1, 1),
      name = 'Spearman r'
    ) +
    scale_fill_gradient2(
      low = alpha(group_cols['non_pCR'], 0.85),
      mid = 'white',
      high = alpha(group_cols['pCR'], 0.85),
      midpoint = 0,
      limits = c(-effect_limit, effect_limit),
      name = 'Node enrichment\npCR vs non-pCR'
    ) +
    scale_linewidth(range = c(0.55, 1.35), guide = 'none') +
    scale_linetype_identity() +
    coord_equal(
      xlim = c(-0.16, triangle_width + 0.16),
      ylim = c(-0.25, triangle_height + 0.58),
      clip = 'off'
    ) +
    facet_wrap(~ panel, nrow = 1) +
    labs(
      title = plot_title,
      subtitle = '* P<0.05, ** P<0.01, *** P<0.001'
    ) +
    theme_void(base_size = 9) +
    theme(
      strip.text = element_blank(),
      legend.position = 'bottom',
      legend.box = 'horizontal',
      legend.title = element_text(size = 8),
      legend.text = element_text(size = 7.5),
      plot.title = element_text(size = 10.5, face = 'bold'),
      plot.subtitle = element_text(size = 7.8),
      panel.spacing = unit(2.7, 'mm'),
      plot.margin = margin(4, 6, 4, 6)
    )
  
  ggsave(
    output_file,
    p_set,
    width = 17.6,
    height = 3.65,
    device = 'svg'
  )
  
  p_set
}

dir.create(
  'figures/Fig5E_broad_screen_eight_sets_horizontal',
  recursive = TRUE,
  showWarnings = FALSE
)

p_first_broad_set <- NULL
for (set_i in seq_len(selected_set_n)) {
  set_table_i <- selected_set_members %>%
    filter(set_rank == set_i)
  
  set_title_i <- selected_set_index$set_title[
    selected_set_index$set_rank == set_i
  ][1]
  
  file_stub_i <- set_title_i %>%
    str_replace_all('[^A-Za-z0-9]+', '_') %>%
    str_replace_all('_+', '_') %>%
    str_replace_all('^_|_$', '')
  
  p_set_i <- plot_two_function_triad_set(
    set_table_i,
    paste0(
      'figures/Fig5E_broad_screen_eight_sets_horizontal/',
      'Fig5E_broad_set_', sprintf('%02d', set_i), '_',
      file_stub_i, '_', analysis_set, '.svg'
    ),
    paste0('Set ', sprintf('%02d', set_i), '. ', set_title_i)
  )
  
  if (set_i == 1L) {
    p_first_broad_set <- p_set_i
  } else {
    rm(p_set_i)
    invisible(gc())
  }
}

